alter table public.omnii_common_primitives
  add column if not exists denominator_scope text not null default 'ecosystem'
    check (denominator_scope in ('universal','ecosystem','domain','technology')),
  add column if not exists reuse_policy text not null default 'reuse'
    check (reuse_policy in ('reuse','extend','compose','adapter_only')),
  add column if not exists external_alignment jsonb not null default '{}'::jsonb,
  add column if not exists domain_examples jsonb not null default '[]'::jsonb;

create index if not exists omnii_common_primitives_denominator_scope_idx
  on public.omnii_common_primitives(denominator_scope, layer_role);

update public.omnii_common_primitives
set denominator_scope='ecosystem', reuse_policy='reuse', updated_at=now()
where denominator_scope is distinct from 'ecosystem';

on conflict (key) do update set
  semantic_class=excluded.semantic_class,
  layer_role=excluded.layer_role,
  canonical_backing=excluded.canonical_backing,
  lifecycle=excluded.lifecycle,
  description=excluded.description,
  provenance=excluded.provenance,
  denominator_scope=excluded.denominator_scope,
  reuse_policy=excluded.reuse_policy,
  external_alignment=excluded.external_alignment,
  domain_examples=excluded.domain_examples,
  updated_at=now();

comment on column public.omnii_common_primitives.denominator_scope is 'Classification of reusable denominator scope: universal cross-domain abstraction, Carbon Actual ecosystem capability, domain capability, or technology implementation.';
comment on column public.omnii_common_primitives.external_alignment is 'Non-binding alignment references to external standards/ontologies. External standards do not become constitutional authority.';
comment on column public.omnii_common_primitives.reuse_policy is 'Whether downstream implementations should reuse, extend, compose, or adapter-only consume the denominator.';
