insert into public.omnii_common_primitives
  (key, semantic_class, layer_role, canonical_backing, lifecycle, description, provenance, denominator_scope, reuse_policy, external_alignment, domain_examples)
values
('thing','THING','foundation','omnii_objects','active','A bearer of identity, description, relationships or participation; physical, digital, social, informational or abstract-as-modeled things are represented without forcing them into a domain taxonomy.','{"source":"OMNII denominator synthesis","basis":"BFO; Schema.org; RDF"}', 'universal','extend','{"bfo":"continuant/independent continuant","schema_org":"Thing","rdf":"Resource"}','["person","organization","property","document","media","machine","resource"]'::jsonb),
('agent','AGENT','foundation','identity / actor contracts','active','An entity that can bear responsibility, participate, act, delegate or be attributed within a modeled system.','{"source":"OMNII denominator synthesis","basis":"PROV; Schema.org; ORG"}', 'universal','extend','{"prov":"Agent","schema_org":"Person|Organization","org":"foaf:Agent"}','["person","organization","human_agent","ai_agent","service_agent"]'::jsonb),
('activity','ACTIVITY','foundation','IO / event / process contracts','active','A bounded occurrence in which actions, processes or interactions take place and which may consume, produce or change entities.','{"source":"OMNII denominator synthesis","basis":"PROV; Schema.org; ActivityStreams"}', 'universal','extend','{"prov":"Activity","schema_org":"Action","activitystreams":"Activity"}','["service","transaction","workflow_step","movement","interaction"]'::jsonb),
('process','PROCESS','foundation','workflow / process runtime','active','An ordered or structured temporal progression consisting of activities, states, transitions or tasks.','{"source":"OMNII denominator synthesis","basis":"BFO; PROV"}', 'universal','extend','{"bfo":"Process","prov":"Activity"}','["workflow","journey","manufacturing","service_delivery","learning"]'::jsonb),
