('identity','IDENTITY','foundation','omnii_objects / ROOT / HAPI','active','Persistent reference to the same modeled entity across representations and systems, subject to verification and provenance.','{"source":"OMNII existing canonical","basis":"Schema.org identifier; PROV attribution; RDF resources"}', 'universal','reuse','{"schema_org":"identifier","rdf":"IRI/resource identity","prov":"Agent/Entity"}','["person","organization","device","account","document"]'::jsonb),
